{"path": "/work/live2/inventory.py", "content": """"Inventory tracking: simple quantities of named items."""

from __future__ import annotations


class Inventory:
    """A mapping of item name -> non-negative integer quantity."""

    def __init__(self) -> None:
        self._counts: dict[str, int] = {}

    def add(self, name: str, qty: int) -> None:
        """Add ``qty`` units of ``name``. Raises ``ValueError`` if ``qty`` is negative."""
        if qty < 0:
            raise ValueError(f"cannot add negative quantity: {qty}")
        total = self._counts.get(name, 0) + qty
        if total == 0:
            self._counts.pop(name, None)
        else:
            self._counts[name] = total

    def remove(self, name: str, qty: int) -> None:
        """Remove ``qty`` units of ``name``. Raises ``ValueError`` if not enough stock."""
        current = self._counts.get(name, 0)
        if current < qty:
            raise ValueError(f"not enough stock of {name!r}: have {current}, need {qty}")
        remaining = current - qty
        if remaining == 0:
            self._counts.pop(name, None)
        else:
            self._counts[name] = remaining

    def count(self, name: str) -> int:
        """Return the current quantity of ``name`` (0 if absent)."""
        return self._counts.get(name, 0)

    def total(self) -> int:
        """Return the total quantity across all items."""
        return sum(self._counts.values())

    def items(self) -> list[tuple[str, int]]:
        """Return ``(name, qty)`` pairs sorted by name."""
        return sorted(self._counts.items())

    def low_stock(self, threshold: int) -> list[str]:
        """Return names whose quantity is below ``threshold`` (sorted)."""
        return sorted(n for n, q in self._counts.items() if q < threshold)

    def to_csv(self) -> str:
        """Serialize to CSV text with a header line and a trailing newline."""
        lines = ["name,qty"]
        for name, qty in sorted(self._counts.items()):
            lines.append(f"{name},{qty}")
        return "\n".join(lines) + "\n"

    @classmethod
    def from_csv(cls, text: str) -> "Inventory":
        """Build an inventory from CSV text produced by :meth:`to_csv`."""
        inv = cls()
        stripped = text.strip()
        if not stripped:
            return inv
        lines = stripped.split("\n")
        # Skip the header row.
        for line in lines[1:]:
            line = line.strip()
            if not line:
                continue
            name, qty = line.split(",", 1)
            inv.add(name, int(qty))
        return inv
