{"path": "/work/live2/ledger.py", "content": """"Personal finance ledger: posting entries and reporting on them."""

from __future__ import annotations

from datetime import datetime
from decimal import Decimal, InvalidOperation
from typing import Any


class Entry:
    """A single ledger line item."""

    __slots__ = ("date", "desc", "amount", "category")

    def __init__(self, date: str, desc: str, amount: Decimal, category: str) -> None:
        self.date = date
        self.desc = desc
        self.amount = amount
        self.category = category

    def __repr__(self) -> str:
        return (
            f"Entry(date={self.date!r}, desc={self.desc!r}, "
            f"amount={self.amount!r}, category={self.category!r})"
        )


def parse_amount(value: Any) -> Decimal:
    """Parse a monetary amount from a string.

    Handles:
      * plain decimals:        ``"12.50"`` -> ``Decimal("12.50")``
      * European grouping:     ``"1.234,56"`` -> ``Decimal("1234.56")``
      * currency symbols:      ``"R$ 10,00"`` -> ``Decimal("10.00")``
      * negative in parens:    ``"(5.00)"`` -> ``Decimal("-5.00")``

    Raises ``ValueError`` if the string cannot be interpreted as a number.
    """
    if not isinstance(value, str):
        raise ValueError(f"amount must be a string, got {type(value).__name__}")

    raw = value.strip()
    if not raw:
        raise ValueError("empty amount")

    # Parentheses indicate a negative value.
    negative = "(" in raw

    # Keep digits, decimal points and commas; drop currency symbols / whitespace.
    cleaned = "".join(c for c in raw if c.isdigit() or c in ".,")

    if not cleaned:
        raise ValueError(f"cannot parse amount: {value!r}")

    if "," in cleaned and "." in cleaned:
        # Both present: dot = thousands separator, comma = decimal separator.
        cleaned = cleaned.replace(".", "").replace(",", ".")
    elif "," in cleaned:
        # Only comma: it is the decimal separator.
        cleaned = cleaned.replace(",", ".")
    # else: only dot (or nothing) -> dot is the decimal separator.

    try:
        amount = Decimal(cleaned)
    except InvalidOperation as exc:  # pragma: no cover - guarded above
        raise ValueError(f"cannot parse amount: {value!r}") from exc

    if negative:
        amount = -amount
    return amount


class Ledger:
    """An ordered collection of :class:`Entry` objects."""

    def __init__(self) -> None:
        self._entries: list[Entry] = []

    # ------------------------------------------------------------------ posting

    def post(self, date: str, desc: str, amount: Any, category: str) -> Entry:
        """Add a new entry. ``date`` must be a valid ``YYYY-MM-DD`` string."""
        try:
            datetime.strptime(date, "%Y-%m-%d")
        except (ValueError, TypeError) as exc:
            raise ValueError(f"invalid date: {date!r}") from exc
        entry = Entry(date, desc, parse_amount(amount), category)
        self._entries.append(entry)
        return entry

    # ------------------------------------------------------------------ queries

    def entries(self) -> list[Entry]:
        """Return a copy of all entries in posting order."""
        return list(self._entries)

    def balance(self, until: str | None = None) -> Decimal:
        """Sum all amounts, optionally restricted to entries on/before ``until``."""
        total = Decimal("0")
        for e in self._entries:
            if until is None or e.date <= until:
                total += e.amount
        return total

    def by_category(self) -> dict[str, Decimal]:
        """Return ``category -> total amount``."""
        totals: dict[str, Decimal] = {}
        for e in self._entries:
            totals[e.category] = totals.get(e.category, Decimal("0")) + e.amount
        return totals

    def monthly(self) -> dict[str, Decimal]:
        """Return ``"YYYY-MM" -> total amount`` per calendar month."""
        totals: dict[str, Decimal] = {}
        for e in self._entries:
            month = e.date[:7]
            totals[month] = totals.get(month, Decimal("0")) + e.amount
        return totals

    def search(self, desc: str) -> list[Entry]:
        """Return entries whose description contains ``desc``."""
        return [e for e in self._entries if desc in e.desc]

    def largest_expense(self) -> Entry:
        """Return the entry with the largest (most negative) amount."""
        if not self._entries:
            raise ValueError("no entries")
        return min(self._entries, key=lambda e: e.amount)

    def budget_alerts(self, budget: dict[str, Decimal]) -> list[str]:
        """Return sorted categories where spending exceeds the budget limit."""
        alerts: list[str] = []
        for category, limit in budget.items():
            spent = abs(self.by_category().get(category, Decimal("0")))
            if spent > limit:
                alerts.append(category)
        return sorted(alerts)

    # ------------------------------------------------------------------ mutation

    def undo(self) -> Entry:
        """Remove and return the most recently posted entry."""
        if not self._entries:
            raise IndexError("nothing to undo")
        return self._entries.pop()

    # ------------------------------------------------------------------ (de)serialization

    def to_json(self) -> list[dict[str, str]]:
        """Serialize entries to a JSON-friendly list of dicts."""
        return [
            {
                "date": e.date,
                "desc": e.desc,
                "amount": str(e.amount),
                "category": e.category,
            }
            for e in self._entries
        ]

    @classmethod
    def from_json(cls, data: list[dict[str, str]]) -> "Ledger":
        """Rebuild a ledger from data produced by :meth:`to_json`."""
        ledger = cls()
        for item in data:
            ledger.post(
                item["date"], item["desc"], item["amount"], item["category"]
            )
        return ledger

    # ------------------------------------------------------------------ reporting

    def report(self) -> str:
        """Render a textual report grouped by category with a grand total."""
        lines: list[str] = []
        for category in sorted(self.by_category()):
            amount = self.by_category()[category]
            lines.append(f"{category}  {amount}\n")
        lines.append(f"TOTAL  {self.balance()}\n")
        return "".join(lines)
