{"content": """"Regression tests for newly added logic (parse_amount sign handling)."""

import unittest
from decimal import Decimal

from ledger import Ledger, parse_amount


class ParseAmountSignTests(unittest.TestCase):
    def test_leading_minus(self):
        # Regression: a leading "-" must be preserved, not stripped.
        self.assertEqual(parse_amount("-1500.00"), Decimal("-1500.00"))

    def test_parens_negative(self):
        self.assertEqual(parse_amount("(5.00)"), Decimal("-5.00"))

    def test_zero_sign(self):
        # "-0.00" parses to a negative zero-equivalent Decimal.
        self.assertEqual(parse_amount("-0.00"), Decimal("0.00"))

    def test_large_negative_european(self):
        # Negative European-grouped amount keeps both grouping handling and sign.
        self.assertEqual(parse_amount("-1.234,56"), Decimal("-1234.56"))


class LedgerSignRegressionTests(unittest.TestCase):
    def test_balance_uses_signed_amounts(self):
        l = Ledger()
        l.post("2026-01-01", "rent", "-1500.00", "housing")
        l.post("2026-01-02", "salary", "5000.00", "income")
        self.assertEqual(l.balance(), Decimal("3500.00"))
        self.assertEqual(l.largest_expense().amount, Decimal("-1500.00"))


if __name__ == "__main__":
    unittest.main()
